import React, { useState, useEffect, useCallback } from 'react';
import './UserPanel.css';

// Utility function
const formatFileSize = (bytes) => {
  if (bytes >= 1024 * 1024 * 1024) return (bytes / (1024 * 1024 * 1024)).toFixed(2) + ' GB';
  if (bytes >= 1024 * 1024) return (bytes / (1024 * 1024)).toFixed(2) + ' MB';
  if (bytes >= 1024) return (bytes / 1024).toFixed(1) + ' KB';
  return bytes + ' B';
};

// File type detection and preview utilities
const getFileType = (filename) => {
  const ext = filename.toLowerCase().split('.').pop();
  const name = filename.toLowerCase();

  if (['jpg', 'jpeg', 'png', 'gif', 'bmp', 'webp', 'svg'].includes(ext)) return 'image';
  if (['mp4', 'avi', 'mov', 'wmv', 'flv', 'webm', 'mkv'].includes(ext)) return 'video';
  if (['mp3', 'wav', 'flac', 'aac', 'ogg'].includes(ext)) return 'audio';
  if (['pdf'].includes(ext)) return 'pdf';
  if (['doc', 'docx'].includes(ext)) return 'word';
  if (['xls', 'xlsx'].includes(ext)) return 'excel';
  if (['ppt', 'pptx'].includes(ext)) return 'powerpoint';
  if (['txt', 'md', 'json', 'xml', 'html', 'css', 'js', 'py', 'java', 'cpp', 'c', 'php'].includes(ext)) return 'text';
  if (['zip', 'rar', '7z', 'tar', 'gz'].includes(ext)) return 'archive';
  return 'file';
};

const getFileIcon = (filename) => {
  const type = getFileType(filename);
  const icons = {
    image: '🖼️',
    video: '🎥',
    audio: '🎵',
    pdf: '📄',
    word: '📝',
    excel: '📊',
    powerpoint: '📽️',
    text: '📄',
    archive: '📦',
    file: '📄'
  };
  return icons[type] || '📄';
};

const canPreview = (filename) => {
  const type = getFileType(filename);
  return ['image', 'video', 'pdf', 'text'].includes(type);
};

const getPreviewUrl = (fileId, filename) => {
  const type = getFileType(filename);
  if (type === 'image') return `/api/files/preview/${fileId}`;
  if (type === 'video') return `/api/files/preview/${fileId}`;
  if (type === 'pdf') return `/api/files/preview/${fileId}`;
  return null;
};

const UserPanel = ({ user, onLogout, onBackToFolders }) => {
  console.log('🎯 UserPanel se está renderizando con user:', user);

  const [files, setFiles] = useState([]);
  const [currentView, setCurrentView] = useState('privada');
  const [currentPath, setCurrentPath] = useState([]);
  const [loading, setLoading] = useState(false); // Cambiar a false para evitar loading inicial
  // const [sidebarExpanded, setSidebarExpanded] = useState(true); // Comentado por ahora
  const [uploadMenuOpen, setUploadMenuOpen] = useState(false);
  const [sharedFolders, setSharedFolders] = useState([]);
  const [sharedDropdownOpen, setSharedDropdownOpen] = useState(false);
  const [storageUsed, setStorageUsed] = useState(0);
  const [storageLimit] = useState(5 * 1024 * 1024 * 1024); // 5GB
  const [showCreateFolderModal, setShowCreateFolderModal] = useState(false);
  const [newFolderName, setNewFolderName] = useState('');
  const [showRenameModal, setShowRenameModal] = useState(false);
  const [renameItem, setRenameItem] = useState(null);
  const [renameValue, setRenameValue] = useState('');

  // Nuevos estados para vista interactiva
  const [zoomLevel, setZoomLevel] = useState(1);
  const [showFileViewer, setShowFileViewer] = useState(false);
  const [viewerFile, setViewerFile] = useState(null);
  const [hoveredFile, setHoveredFile] = useState(null);
  const [hoverPreview, setHoverPreview] = useState(null);

const loadFiles = useCallback(async () => {
  try {
    setLoading(true);
    const pathParam = currentPath.length > 0 ? `?path=${encodeURIComponent(currentPath.join('/'))}` : '';
    const response = await fetch(`/api/files${pathParam}`, {
      headers: {
        'Authorization': `Bearer ${user?.token}`
      }
    });
    const data = await response.json();
    setFiles(data.files || []);
    setStorageUsed(data.storageUsed || 0);
  } catch (error) {
    console.error('Error loading files:', error);
  } finally {
    setLoading(false);
  }
}, [user?.token, currentPath]);

const loadSharedFolders = useCallback(async () => {
  try {
    const response = await fetch('/api/files/shared-folders', {
      headers: {
        'Authorization': `Bearer ${user?.token}`
      }
    });
    const data = await response.json();
    setSharedFolders(data.folders || []);
  } catch (error) {
    console.error('Error loading shared folders:', error);
  }
}, [user?.token]);

useEffect(() => {
  loadFiles();
  loadSharedFolders();
}, [currentView, currentPath, loadFiles, loadSharedFolders]);

  const handleFileUpload = async (files) => {
    try {
      const formData = new FormData();
      
      // Agregar todos los archivos al FormData
      for (let file of files) {
        formData.append('files', file);
      }
      
      formData.append('path', currentPath.join('/'));

      const response = await fetch('/api/files/upload', {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${user?.token}`
        },
        body: formData
      });

      if (!response.ok) {
        throw new Error('Error uploading files');
      }

      const result = await response.json();
      console.log('Upload result:', result);
      loadFiles(); // Recargar archivos después de subir
    } catch (error) {
      console.error('Error uploading files:', error);
      alert('Error al subir archivos: ' + error.message);
    }
  };

  const handleFolderUpload = async (files) => {
    try {
      // Handle folder upload (webkitdirectory)
      for (let file of files) {
        const relativePath = file.webkitRelativePath;
        const formData = new FormData();
        formData.append('file', file);
        formData.append('path', currentPath.join('/'));
        formData.append('relativePath', relativePath);

        const response = await fetch('/api/files/upload-folder', {
          method: 'POST',
          headers: {
            'Authorization': `Bearer ${user?.token}`
          },
          body: formData
        });

        if (!response.ok) {
          throw new Error('Error uploading folder');
        }
      }
      loadFiles(); // Recargar archivos después de subir
    } catch (error) {
      console.error('Error uploading folder:', error);
    }
  };

  const handleCreateFolder = async () => {
    if (!newFolderName.trim()) {
      alert('Por favor ingresa un nombre para la carpeta');
      return;
    }

    try {
      const response = await fetch('/api/files/folder', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${user?.token}`
        },
        body: JSON.stringify({
          name: newFolderName.trim(),
          path: currentPath.join('/')
        })
      });

      const result = await response.json();
      
      if (result.success) {
        setShowCreateFolderModal(false);
        setNewFolderName('');
        loadFiles(); // Recargar archivos
      } else {
        alert('Error al crear carpeta: ' + result.message);
      }
    } catch (error) {
      console.error('Error creating folder:', error);
      alert('Error al crear carpeta');
    }
  };

  const handleDeleteItem = async (item) => {
    // eslint-disable-next-line no-restricted-globals
    if (!confirm(`¿Estás seguro de que quieres eliminar "${item.name}"?`)) {
      return;
    }

    try {
      const response = await fetch(`/api/files/${item.id}`, {
        method: 'DELETE',
        headers: {
          'Authorization': `Bearer ${user?.token}`
        }
      });

      const result = await response.json();
      
      if (result.success) {
        loadFiles(); // Recargar archivos
      } else {
        alert('Error al eliminar: ' + result.message);
      }
    } catch (error) {
      console.error('Error deleting item:', error);
      alert('Error al eliminar');
    }
  };

  const handleRenameItem = async () => {
    if (!renameValue.trim()) {
      alert('Por favor ingresa un nuevo nombre');
      return;
    }

    try {
      const response = await fetch(`/api/files/${renameItem.id}/rename`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${user?.token}`
        },
        body: JSON.stringify({
          newName: renameValue.trim()
        })
      });

      const result = await response.json();
      
      if (result.success) {
        setShowRenameModal(false);
        setRenameItem(null);
        setRenameValue('');
        loadFiles(); // Recargar archivos
      } else {
        alert('Error al renombrar: ' + result.message);
      }
    } catch (error) {
      console.error('Error renaming item:', error);
      alert('Error al renombrar');
    }
  };

  const openRenameModal = (item) => {
    setRenameItem(item);
    setRenameValue(item.name);
    setShowRenameModal(true);
  };

  const changeView = (view) => {
    setCurrentView(view);
    setCurrentPath([]);
  };

  const navigateToFolder = (folderName) => {
    setCurrentPath([...currentPath, folderName]);
  };

  const goBack = () => {
    if (currentPath.length > 0) {
      setCurrentPath(currentPath.slice(0, -1));
    }
  };

  const getCurrentFiles = () => {
    return files;
  };

  const getStoragePercentage = () => {
    return Math.min(100, (storageUsed / storageLimit) * 100);
  };

  // Funciones para vista interactiva
  const handleZoomIn = () => {
    setZoomLevel(prev => Math.min(prev + 0.25, 2));
  };

  const handleZoomOut = () => {
    setZoomLevel(prev => Math.max(prev - 0.25, 0.5));
  };

  const handleZoomReset = () => {
    setZoomLevel(1);
  };

  const openFileViewer = (file) => {
    setViewerFile(file);
    setShowFileViewer(true);
  };

  const closeFileViewer = () => {
    setShowFileViewer(false);
    setViewerFile(null);
  };

  const handleFileHover = async (file) => {
    if (!file || file.type === 'folder') return;

    setHoveredFile(file);

    // Generar preview para hover si es posible
    if (canPreview(file.name)) {
      try {
        const previewUrl = getPreviewUrl(file.id, file.name);
        if (previewUrl) {
          setHoverPreview({ url: previewUrl, type: getFileType(file.name) });
        }
      } catch (error) {
        console.error('Error generando preview:', error);
      }
    }
  };

  const handleFileLeave = () => {
    setHoveredFile(null);
    setHoverPreview(null);
  };

  return (
    <div className="user-panel">
      {/* Background */}
      <div className="bg"></div>

      {/* Sidebar */}
      <div className="sidebar">
        {/* Logo */}
        <div className="logo">
          <img className="logo-img" src="/icons/nube.svg" alt="Nube" />
          <span>Nube Personal</span>
        </div>

        {/* Upload Button */}
        <div className="upload-btn-wrapper">
          <button
            className="upload-btn"
            onClick={() => setUploadMenuOpen(!uploadMenuOpen)}
          >
            <span>⬆️</span> Subir
          </button>
          {uploadMenuOpen && (
            <div className="mini-menu-frosted">
              <button
                className="mini-menu-item"
                onClick={() => document.getElementById('fileInput').click()}
              >
                📄 Subir archivos
              </button>
              <button
                className="mini-menu-item"
                onClick={() => document.getElementById('folderInput').click()}
              >
                📁 Subir carpeta
              </button>
              <button
                className="mini-menu-item"
                onClick={() => setShowCreateFolderModal(true)}
              >
                ➕ Nueva carpeta
              </button>
            </div>
          )}
        </div>

        {/* Navigation */}
        <div className="sidebar-nav">
          <button
            className={`sidebar-btn ${currentView === 'privada' ? 'active' : ''}`}
            onClick={() => changeView('privada')}
          >
            <span>🗂️</span> Mi unidad
          </button>

          {/* Shared Folders Dropdown */}
          <div className="dropdown-container">
            <button
              className={`sidebar-btn ${currentView.startsWith('shared') ? 'active' : ''}`}
              onClick={() => setSharedDropdownOpen(!sharedDropdownOpen)}
            >
              <span>🌍</span> Compartidos
              <span className={`dropdown-arrow ${sharedDropdownOpen ? 'open' : ''}`}>▾</span>
            </button>
            {sharedDropdownOpen && (
              <div className="dropdown-content">
                <div className="dropdown-section">
                  <button className="dropdown-item" onClick={() => changeView('public')}>
                    📂 Compartido general
                  </button>
                  {sharedFolders.map(folder => (
                    <button
                      key={folder.id}
                      className="dropdown-item"
                      onClick={() => changeView(`shared-${folder.id}`)}
                    >
                      👥 Con {folder.withUser}
                    </button>
                  ))}
                  <button className="dropdown-item" onClick={() => {/* open create shared modal */}}>
                    ➕ Nueva carpeta compartida
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Actions */}
        <div className="sidebar-actions">
          <button className="acciones-btn" onClick={onBackToFolders}>
            ⬅️ Volver
          </button>
          <button className="acciones-btn" onClick={() => window.open('/calendar', '_blank')}>
            📅 Abrir calendario
          </button>
          <button className="acciones-btn" onClick={onLogout}>
            🚪 Cerrar sesión
          </button>
        </div>
      </div>

      {/* Main Panel */}
      <div className="main-panel">
        <div className="panel-header">
          <h1 className="panel-title">
            {currentView === 'privada' ? 'Mi unidad' :
             currentView === 'public' ? 'Compartido general' :
             currentView.startsWith('shared') ? 'Carpeta compartida' :
             'Archivos'}
          </h1>
        </div>

        <div className="file-grid">
          {/* Zoom Controls */}
          <div className="zoom-controls">
            <button className="zoom-btn" onClick={handleZoomOut} disabled={zoomLevel <= 0.5}>
              🔍-
            </button>
            <span className="zoom-level">{Math.round(zoomLevel * 100)}%</span>
            <button className="zoom-btn" onClick={handleZoomIn} disabled={zoomLevel >= 2}>
              🔍+
            </button>
            <button className="zoom-btn" onClick={handleZoomReset}>
              ↺
            </button>
          </div>

          {loading ? (
            <div className="loading">Cargando archivos...</div>
          ) : (
            <>
              {/* Back button */}
              {currentPath.length > 0 && (
                <button className="back-btn" onClick={goBack}>
                  ⬅ Volver
                </button>
              )}

              {/* Files and folders */}
              <div className="files-container" style={{ transform: `scale(${zoomLevel})`, transformOrigin: 'top center' }}>
                {getCurrentFiles().map((item, index) => (
                  <FileItem
                    key={`${item.name}-${index}`}
                    item={item}
                    onFolderClick={navigateToFolder}
                    onDelete={handleDeleteItem}
                    onRename={openRenameModal}
                    onView={openFileViewer}
                    onHover={handleFileHover}
                    onLeave={handleFileLeave}
                    isHovered={hoveredFile?.id === item.id}
                  />
                ))}
              </div>

              {/* Empty state */}
              {getCurrentFiles().length === 0 && !loading && (
                <div className="empty-state">
                  <span>📁</span>
                  <p>No hay archivos en esta carpeta</p>
                </div>
              )}
            </>
          )}
        </div>
      </div>

      {/* Storage Bar */}
      <div className="storage-bar">
        <div className="storage-text">
          {formatFileSize(storageUsed)} de {formatFileSize(storageLimit)}
        </div>
        <div
          className="storage-bar-fill"
          style={{ width: `${getStoragePercentage()}%` }}
        ></div>
      </div>

      {/* Hidden file inputs */}
      <input
        type="file"
        id="fileInput"
        multiple
        style={{ display: 'none' }}
        onChange={(e) => handleFileUpload(e.target.files)}
      />
      <input
        type="file"
        id="folderInput"
        webkitdirectory=""
        style={{ display: 'none' }}
        onChange={(e) => handleFolderUpload(e.target.files)}
      />

      {/* Create Folder Modal */}
      {showCreateFolderModal && (
        <div className="modal-overlay" onClick={() => setShowCreateFolderModal(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <h3>Nueva Carpeta</h3>
            <input
              type="text"
              placeholder="Nombre de la carpeta"
              value={newFolderName}
              onChange={(e) => setNewFolderName(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && handleCreateFolder()}
              autoFocus
            />
            <div className="modal-buttons">
              <button onClick={() => setShowCreateFolderModal(false)}>Cancelar</button>
              <button onClick={handleCreateFolder}>Crear</button>
            </div>
          </div>
        </div>
      )}

      {/* Rename Modal */}
      {showRenameModal && (
        <div className="modal-overlay" onClick={() => setShowRenameModal(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <h3>Renombrar {renameItem?.type === 'folder' ? 'Carpeta' : 'Archivo'}</h3>
            <input
              type="text"
              placeholder="Nuevo nombre"
              value={renameValue}
              onChange={(e) => setRenameValue(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && handleRenameItem()}
              autoFocus
            />
            <div className="modal-buttons">
              <button onClick={() => setShowRenameModal(false)}>Cancelar</button>
              <button onClick={handleRenameItem}>Renombrar</button>
            </div>
          </div>
        </div>
      )}

      {/* File Viewer Modal */}
      {showFileViewer && viewerFile && (
        <FileViewerModal
          file={viewerFile}
          onClose={closeFileViewer}
          user={user}
        />
      )}

      {/* Hover Preview Tooltip */}
      {hoverPreview && hoveredFile && (
        <HoverPreview
          file={hoveredFile}
          preview={hoverPreview}
        />
      )}
    </div>
  );
};

// File Item Component
const FileItem = ({ item, onFolderClick, onDelete, onRename, onView, onHover, onLeave, isHovered }) => {
  const [menuOpen, setMenuOpen] = useState(false);

  const handleClick = () => {
    if (item.type === 'folder') {
      onFolderClick(item.name);
    } else {
      // Si se puede previsualizar, abrir viewer, sino descargar
      if (canPreview(item.name)) {
        onView(item);
      } else {
        window.open(`/api/files/download/${item.id}`, '_blank');
      }
    }
  };

  const handleMenuClick = (e) => {
    e.stopPropagation();
    setMenuOpen(!menuOpen);
  };

  const handleMouseEnter = () => {
    onHover(item);
  };

  const handleMouseLeave = () => {
    onLeave();
  };

  if (item.type === 'file') {
    const fileType = getFileType(item.name);
    const previewUrl = getPreviewUrl(item.id, item.name);

    return (
      <div
        className={`drive-file-row ${isHovered ? 'hovered' : ''}`}
        onClick={handleClick}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
      >
        <div className="thumbnail">
          {previewUrl && fileType === 'image' ? (
            <img
              src={previewUrl}
              alt={item.name}
              onError={(e) => {
                e.target.style.display = 'none';
                e.target.nextSibling.style.display = 'flex';
              }}
            />
          ) : null}
          <div className="file-icon" style={{ display: previewUrl && fileType === 'image' ? 'none' : 'flex' }}>
            {getFileIcon(item.name)}
          </div>
        </div>
        <div className="file-name" title={item.name}>
          {item.name}
        </div>
        <span className="file-size">
          {item.size ? formatFileSize(item.size) : ''}
        </span>
        <div className="menu-container">
          <button className="menu-trespuntos" onClick={handleMenuClick}>
            ⋮
          </button>
          {menuOpen && (
            <div className={`menu-popup ${menuOpen ? 'show' : ''}`}>
              {canPreview(item.name) ? (
                <button onClick={() => { setMenuOpen(false); onView(item); }}>
                  👁 Ver
                </button>
              ) : (
                <button onClick={() => window.open(`/api/files/download/${item.id}`, '_blank')}>
                  👁 Ver
                </button>
              )}
              <button onClick={() => window.open(`/api/files/download/${item.id}?download=true`)}>
                ⬇️ Descargar
              </button>
              <button>📋 Duplicar</button>
              <button>📁 Mover</button>
              <button onClick={() => { setMenuOpen(false); onRename(item); }}>
                ✏️ Renombrar
              </button>
              <button className="danger" onClick={() => { setMenuOpen(false); onDelete(item); }}>
                🗑️ Eliminar
              </button>
            </div>
          )}
        </div>
      </div>
    );
  }

  return (
    <div
      className="folder-chip"
      onClick={handleClick}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
    >
      <span className="folder-icon">📁</span>
      <span className="folder-name" title={item.name}>
        {item.name}
        {item.shared && <span className="shared-label">🤝 Compartida</span>}
      </span>
      <div className="menu-container">
        <button className="menu-trespuntos" onClick={handleMenuClick}>
          ⋮
        </button>
        {menuOpen && (
          <div className={`menu-popup ${menuOpen ? 'show' : ''}`}>
            <button onClick={() => onFolderClick(item.name)}>
              📁 Abrir
            </button>
            <button>📋 Duplicar</button>
            <button>📁 Mover</button>
            <button onClick={() => { setMenuOpen(false); onRename(item); }}>
              ✏️ Renombrar
            </button>
            <button className="danger" onClick={() => { setMenuOpen(false); onDelete(item); }}>
              🗑️ Eliminar
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default UserPanel;

// File Viewer Modal Component
const FileViewerModal = ({ file, onClose, user }) => {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const fileType = getFileType(file.name);
  const previewUrl = getPreviewUrl(file.id, file.name);

  useEffect(() => {
    setLoading(true);
    setError(null);
  }, [file]);

  const handleDownload = () => {
    window.open(`/api/files/download/${file.id}?download=true`, '_blank');
  };

  const renderFileContent = () => {
    switch (fileType) {
      case 'image':
        return (
          <div className="viewer-content image-viewer">
            <img
              src={previewUrl}
              alt={file.name}
              onLoad={() => setLoading(false)}
              onError={() => {
                setError('Error al cargar la imagen');
                setLoading(false);
              }}
              style={{ maxWidth: '100%', maxHeight: '70vh', objectFit: 'contain' }}
            />
          </div>
        );

      case 'video':
        return (
          <div className="viewer-content video-viewer">
            <video
              controls
              onLoadedData={() => setLoading(false)}
              onError={() => {
                setError('Error al cargar el video');
                setLoading(false);
              }}
              style={{ maxWidth: '100%', maxHeight: '70vh' }}
            >
              <source src={previewUrl} />
              Tu navegador no soporta el elemento de video.
            </video>
          </div>
        );

      case 'pdf':
        return (
          <div className="viewer-content pdf-viewer">
            <iframe
              src={previewUrl}
              onLoad={() => setLoading(false)}
              onError={() => {
                setError('Error al cargar el PDF');
                setLoading(false);
              }}
              style={{ width: '100%', height: '70vh', border: 'none' }}
              title={file.name}
            />
          </div>
        );

      case 'text':
        return (
          <TextFileViewer
            fileId={file.id}
            fileName={file.name}
            onLoad={() => setLoading(false)}
            onError={(err) => {
              setError(err);
              setLoading(false);
            }}
          />
        );

      default:
        return (
          <div className="viewer-content unsupported">
            <div className="unsupported-content">
              <span className="file-icon-large">{getFileIcon(file.name)}</span>
              <p>Este tipo de archivo no se puede previsualizar</p>
              <p>Archivo: {file.name}</p>
              <p>Tamaño: {formatFileSize(file.size)}</p>
            </div>
          </div>
        );
    }
  };

  return (
    <div className="modal-overlay file-viewer-overlay" onClick={onClose}>
      <div className="file-viewer-modal" onClick={(e) => e.stopPropagation()}>
        <div className="viewer-header">
          <h3>{file.name}</h3>
          <div className="viewer-actions">
            <button onClick={handleDownload} className="download-btn">
              ⬇️ Descargar
            </button>
            <button onClick={onClose} className="close-btn">
              ✕
            </button>
          </div>
        </div>

        <div className="viewer-body">
          {loading && (
            <div className="viewer-loading">
              <div className="loading-spinner"></div>
              <p>Cargando archivo...</p>
            </div>
          )}

          {error && (
            <div className="viewer-error">
              <p>❌ {error}</p>
              <button onClick={handleDownload}>Descargar archivo</button>
            </div>
          )}

          {!loading && !error && renderFileContent()}
        </div>
      </div>
    </div>
  );
};

// Text File Viewer Component
const TextFileViewer = ({ fileId, fileName, onLoad, onError }) => {
  const [content, setContent] = useState('');

  useEffect(() => {
    const loadTextFile = async () => {
      try {
        const response = await fetch(`/api/files/preview/${fileId}`, {
          headers: {
            'Authorization': `Bearer ${localStorage.getItem('token') || ''}`
          }
        });

        if (!response.ok) throw new Error('Error al cargar el archivo');

        const text = await response.text();
        setContent(text);
        onLoad();
      } catch (error) {
        onError('Error al cargar el archivo de texto');
      }
    };

    loadTextFile();
  }, [fileId, onLoad, onError]);

  return (
    <div className="viewer-content text-viewer">
      <pre className="text-content">{content}</pre>
    </div>
  );
};

// Hover Preview Component
const HoverPreview = ({ file, preview }) => {
  const [position, setPosition] = useState({ x: 0, y: 0 });

  useEffect(() => {
    const handleMouseMove = (e) => {
      setPosition({ x: e.clientX, y: e.clientY });
    };

    document.addEventListener('mousemove', handleMouseMove);
    return () => document.removeEventListener('mousemove', handleMouseMove);
  }, []);

  const renderPreview = () => {
    switch (preview.type) {
      case 'image':
        return (
          <img
            src={preview.url}
            alt={file.name}
            style={{ maxWidth: '200px', maxHeight: '200px', objectFit: 'contain' }}
            onError={(e) => {
              e.target.style.display = 'none';
              e.target.nextSibling.style.display = 'block';
            }}
          />
        );

      case 'video':
        return (
          <video
            style={{ maxWidth: '200px', maxHeight: '200px' }}
            muted
            onMouseEnter={(e) => e.target.play()}
            onMouseLeave={(e) => e.target.pause()}
          >
            <source src={preview.url} />
          </video>
        );

      case 'pdf':
        return (
          <div className="pdf-preview">
            <span>📄</span>
            <p>PDF Preview</p>
          </div>
        );

      default:
        return (
          <div className="file-preview">
            <span>{getFileIcon(file.name)}</span>
            <p>{file.name}</p>
          </div>
        );
    }
  };

  return (
    <div
      className="hover-preview"
      style={{
        left: position.x + 10,
        top: position.y + 10,
        pointerEvents: 'none'
      }}
    >
      {renderPreview()}
      <div className="preview-info">
        <p className="preview-filename">{file.name}</p>
        <p className="preview-size">{formatFileSize(file.size)}</p>
      </div>
    </div>
  );
};
